from math import comb

def check_condition(n):
    results = {}
    # Find valid values of a: n/3 < a <= n/2
    import math
    a_min = math.floor(n/3) + 1
    a_max = math.floor(n/2)

    if a_min > a_max:
        return {n: "No valid values for a."}

    current_n_results = []
    for a in range(a_min, a_max + 1):
        k = n - 2*a

        numerator_comb = a - 1
        denominator_comb = k - 1

        # k must be positive since n is odd (and >= 5)
        if k <= 0:
             is_divisible = False # Safety check
        elif denominator_comb < 0 or numerator_comb < denominator_comb:
            # This case happens if k=1 (denominator_comb=0) or k=0 (denominator_comb=-1), which are fine.
            # However, if k-1 > a-1, the coefficient is 0, which is divisible by k (if k>0).
            # We rely on comb() to handle cases where the lower index is negative.
            try:
                binomial_coeff = comb(numerator_comb, denominator_comb)
                is_divisible = (binomial_coeff % k == 0)
            except ValueError:
                is_divisible = False
        else:
            try:
                binomial_coeff = comb(numerator_comb, denominator_comb)
                is_divisible = (binomial_coeff % k == 0)
            except ValueError:
                is_divisible = False

        current_n_results.append((a, k, is_divisible))

    results[n] = current_n_results
    return results

Ns = [5, 7, 11, 13, 17, 19]
verification_results = {}
for n in Ns:
    verification_results[n] = check_condition(n)

print("--- Verification Results ---")
